function chunkConsecutive(arr, predicate) {
  return arr.reduce((acc, x) => {
    const last = acc[acc.length - 1];
    if (last && last[last.length - 1] < x) {
      last.push(x);
    } else {
      acc.push([x]);
    }
    return acc;
  }, []);
}
